47.     Console.WriteLine($"LogLossReduction: {metrics.LogLossReduction:F4}");
48. 
49.     mlContext.Model.Save(model, data.Schema, modelPath);
50.     Console.WriteLine($"Model saved to {modelPath}");
51. }
